def VTask.replaceVertex : {V : Type u_1} -> (G : SimpleGraph V) -> (s t : V) -> [DecidableEq V] -> SimpleGraph V :=
fun G s t dec =>
let s_neighbors := G.Adj s;
let new_adj := fun v => 
  if v = s then false
  else if v = t then s_neighbors.erase v
  else if s_neighbors.contains v then true
  else false;
SimpleGraph.ofRel (λ v w => new_adj v w)
